package main

import (
	"context"
	"log/slog"

	"github.com/wailsapp/wails/v3/pkg/application"
	"github.com/wailsapp/wails/v3/pkg/services/kvstore"
)

// AppService is the frontend-facing service: its exported methods become
// callable from JavaScript through the generated bindings
// (frontend/bindings, regenerated by every build). In v3 services are plain
// Go structs — dependencies are injected by hand, never hidden in a context.
type AppService struct {
	app *application.App
	kvs *kvstore.KVStoreService
}

// GetVersion returns the release this binary was built from; the frontend
// shows it next to the greeting.
func (s *AppService) GetVersion() string {
	return version
}

// SaveWindowSize persists the window size reported by the frontend's
// debounced resize handler. AutoSave writes the store to disk on every Set,
// so nothing is lost if the app dies right after a resize.
func (s *AppService) SaveWindowSize(w, h int) {
	if err := s.kvs.Set(prefsWindowWidthKey, w); err != nil {
		slog.Warn("save window size", "error", err)
		return
	}
	if err := s.kvs.Set(prefsWindowHeightKey, h); err != nil {
		slog.Warn("save window size", "error", err)
	}
}

// maybeCheckForUpdates checks for a newer release on launch, silently. Any
// failure or "no update" is swallowed — a nagging dialog on a network blip
// is worse than missing an update until the next launch. Dev/unstamped
// builds never hit the network; Help → Check for Updates bypasses that gate.
func (s *AppService) maybeCheckForUpdates() {
	if !shouldCheckUpdate(version) {
		return
	}
	go func() {
		rel, err := s.app.Updater.Check(context.Background())
		if err != nil {
			slog.Info("update check failed", "error", err)
			return
		}
		if rel == nil {
			return
		}
		// An update exists: open the framework's update window, which walks
		// download → verify → stage and waits for the user to restart.
		if err := s.app.Updater.CheckAndInstall(context.Background()); err != nil {
			slog.Info("update flow failed", "error", err)
		}
	}()
}

// checkForUpdateNow is the Help → Check for Updates action. Unlike the
// startup check it always reports an outcome: CheckAndInstall opens the
// update window even when the app is already up to date (or the check
// failed), so local builds and opted-out users get feedback too.
func (s *AppService) checkForUpdateNow() {
	go func() {
		if err := s.app.Updater.CheckAndInstall(context.Background()); err != nil {
			slog.Info("update flow failed", "error", err)
		}
	}()
}

// shouldCheckUpdate gates the startup update check: dev/unstamped builds
// never hit the network. The Help → Check for Updates action bypasses it.
func shouldCheckUpdate(current string) bool {
	return current != "" && current != "dev"
}
